'use strict';
let data=[],saved=new Set();const selectedMajors=new Set(),selectedMinors=new Set(),selectedCountries=new Set(),selectedSubjects=new Set();let applied={},countryChoices=[],subjectChoices=[];try{const value=JSON.parse(localStorage.getItem('next-chapter-2027-shortlist')||'[]');if(Array.isArray(value))saved=new Set(value.map(String))}catch{}
const $=id=>document.getElementById(id),flags={'Canada':'🇨🇦','United Kingdom':'🇬🇧','Singapore':'🇸🇬','Australia':'🇦🇺','Netherlands':'🇳🇱','Germany':'🇩🇪'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kinds={'single':'One major / specialist','major-minor':'One major + one minor','multiple-minors':'One major + multiple minors','double':'Two majors','double-minor':'Two majors + minor(s)','joint':'Named joint degree','double-degree':'Two degrees','concentration':'Concentration'};
function draftFilters(){return {query:$('search').value.trim(),countries:[...selectedCountries],subjects:[...selectedSubjects],subjectMode:$('subjectMode').value,status:$('status').value,delivery:$('delivery').value,savedOnly:$('savedOnly').checked,english:$('english').checked,majors:[...selectedMajors],minors:[...selectedMinors],structure:$('structure').value,minorNumber:$('minorNumber').value,documentedOnly:$('documentedOnly').checked}}
function filters(){return {...applied,saved:[...saved]}}
function updateDraftUI(){
 $('countrySummary').textContent=selectedCountries.size?[...selectedCountries].join(', '):'All countries';$('subjectSummary').textContent=selectedSubjects.size?[...selectedSubjects].join(', '):'All listed subjects';
 $('selectionChips').innerHTML=[...selectedCountries].map(v=>`<button class="selection-chip" type="button" data-group="country" data-value="${esc(v)}" aria-label="Remove country: ${esc(v)}">${esc(v)} ×</button>`).join('')+[...selectedSubjects].map(v=>`<button class="selection-chip" type="button" data-group="subject" data-value="${esc(v)}" aria-label="Remove subject: ${esc(v)}">${esc(v)} ×</button>`).join('');
 $('roleHelp').hidden=!selectedSubjects.size;
 $('subjectRoles').innerHTML=[...selectedSubjects].map(v=>`<label class="subject-role"><span>${esc(v)}</span><select data-role-subject="${esc(v)}" aria-label="Role for ${esc(v)}"><option value="either" ${!selectedMajors.has(v)&&!selectedMinors.has(v)?'selected':''}>Either role</option><option value="major" ${selectedMajors.has(v)?'selected':''}>Major</option><option value="minor" ${selectedMinors.has(v)?'selected':''}>Minor</option></select></label>`).join('');
}
function markDirty(){updateDraftUI();const changed=JSON.stringify(draftFilters())!==JSON.stringify(applied);$('searchState').classList.toggle('pending',changed);$('searchState').textContent=changed?'Selections changed. Select Search listed programmes to rerun. The table still shows your previous search.':`Showing ${filtered().length} saved routes for the applied selections. Source: research snapshot, 30 October 2026.`;}
function runSearch(){applied=draftFilters();for(const d of document.querySelectorAll('.multi-picker'))d.open=false;render();$('searchState').classList.remove('pending');const c=applied.countries.length?applied.countries.join(', '):'all listed countries',s=applied.subjects.length?applied.subjects.join(', '):'all listed subjects';$('searchState').textContent=`Search complete: ${filtered().length} saved routes · ${c} · ${s}. Source: research snapshot, 30 October 2026. No live web search was run.`;}
function filtered(){return StudyMatch.filterRoutes(data,filters()).sort((a,b)=>a[$('sort').value].localeCompare(b[$('sort').value])||a.university.localeCompare(b.university))}
function planHTML(p){return `<div class="study-plan"><div class="plan-kind">${esc(kinds[StudyMatch.structureOf(p)]||'Study plan')}</div><div class="plan-role"><strong>${p.kind==='joint'?'Joint subjects':p.kind==='concentration'?'Concentration':p.kind==='double-degree'?'Degree fields':'Major'+(p.majors.length>1?'s':'')}:</strong> ${esc(p.majors.join(' + '))}</div><div class="plan-role"><strong>Minor${p.minors.length>1?'s':''}:</strong> ${esc(p.minors.length?p.minors.join(' + '):'None recorded')}</div><div class="plan-evidence ${p.evidence==='Documented route'?'':'conditional'}">${esc(p.evidence)}</div>${p.note?`<div class="plan-note">${esc(p.note)}</div>`:''}<a class="plan-source" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Structure evidence ↗</a></div>`}
function render(){const f=filters(),rows=filtered();updateDraftUI();$('count').textContent=rows.length;$('shortCount').textContent=saved.size;$('totalRoutes').textContent=data.length;$('foreignCount').textContent=data.filter(r=>r.delivery!=='Domestic institution').length;$('empty').hidden=!!rows.length;
 $('rows').innerHTML=rows.map(r=>{const plans=StudyMatch.matchingPlans(r,f);return `<tr><td><span class="country-flag" aria-hidden="true">${flags[r.country]}</span>${esc(r.country)}</td><td><b>${esc(r.university)}</b><span class="delivery-label">${esc(r.delivery)}</span><div class="awarding">Award: ${esc(r.awardingUniversity)}<br>Awarding country: ${esc(r.awardingCountry)}${r.networkCountry?`<br>Network origin: ${esc(r.networkCountry)}`:''}<br>Teaching: ${esc(r.provider)}</div><div class="language">${esc(r.language)}</div></td><td><b>${esc(r.degree)}</b><div class="structure">${esc(r.structure)}</div>${r.subjects.split(',').map(s=>`<span class="subject-pill">${esc(s)}</span>`).join('')}</td><td>${plans.slice(0,1).map(planHTML).join('')}${plans.length>1?`<details class="plan-extra"><summary>${plans.length-1} more matching study plan${plans.length>2?'s':''}</summary>${plans.slice(1).map(planHTML).join('')}</details>`:''}</td><td>${r.steps.split(' → ').map((s,i)=>`${i+1}. ${esc(s)}`).join('<br>')}</td><td>${esc(r.dates)}</td><td>${esc(r.start)}</td><td><span class="badge ${r.status==='Published'?'published':r.status==='To verify'?'verify':'combo'}">${esc(r.status)}</span><a class="source" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Official source ↗</a><div class="language">Checked ${esc(r.checked)}</div></td><td><button class="star" data-save="${r.id}" aria-label="${saved.has(r.id)?'Remove from':'Add to'} shortlist: ${esc(r.university)}, ${esc(r.degree)}" aria-pressed="${saved.has(r.id)}">${saved.has(r.id)?'★':'☆'}</button></td></tr>`}).join('')}
function reset(){for(const id of ['search','status','structure','minorNumber','delivery'])$(id).value='';$('subjectMode').value='any';for(const id of ['savedOnly','english','documentedOnly'])$(id).checked=false;for(const set of [selectedMajors,selectedMinors,selectedCountries,selectedSubjects])set.clear();for(const el of document.querySelectorAll('.option-list input[type=checkbox]'))el.checked=false;for(const d of document.querySelectorAll('.multi-picker'))d.open=false;$('sort').value='country';runSearch()}
function toast(s){$('toast').textContent=s;$('toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2400)}
for(const id of ['search','status','savedOnly','english','structure','minorNumber','delivery','documentedOnly','subjectMode'])$(id).addEventListener(id==='search'?'input':'change',markDirty);
$('sort').addEventListener('change',render);$('runSearch').addEventListener('click',runSearch);$('search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();runSearch()}});
$('reset').addEventListener('click',reset);$('emptyReset').addEventListener('click',reset);
for(const [id,selection] of [['countryOptions',selectedCountries],['subjectOptions',selectedSubjects]])$(id).addEventListener('change',e=>{if(!e.target.matches('input[type=checkbox]'))return;if(e.target.checked)selection.add(e.target.value);else{selection.delete(e.target.value);if(id==='subjectOptions'){selectedMajors.delete(e.target.value);selectedMinors.delete(e.target.value)}}markDirty()});
$('subjectRoles').addEventListener('change',e=>{if(!e.target.matches('[data-role-subject]'))return;const value=e.target.dataset.roleSubject;selectedMajors.delete(value);selectedMinors.delete(value);if(e.target.value==='major')selectedMajors.add(value);if(e.target.value==='minor')selectedMinors.add(value);markDirty()});
$('selectionChips').addEventListener('click',e=>{const b=e.target.closest('[data-group]');if(!b)return;const set=b.dataset.group==='country'?selectedCountries:selectedSubjects;set.delete(b.dataset.value);if(b.dataset.group==='subject'){selectedMajors.delete(b.dataset.value);selectedMinors.delete(b.dataset.value)}const root=$(b.dataset.group==='country'?'countryOptions':'subjectOptions');for(const el of root.querySelectorAll('input'))if(el.value===b.dataset.value)el.checked=false;markDirty()});
function addChoice(type){const country=type==='country',el=$(country?'newCountry':'newSubject');let value=el.value.trim().replace(/\s+/g,' ');if(!value)return;const aliases=country?{'uk':'United Kingdom','england':'United Kingdom','holland':'Netherlands','the netherlands':'Netherlands'}:{};value=aliases[value.toLowerCase()]||value;let choices=country?countryChoices:subjectChoices;const existing=choices.find(v=>v.toLowerCase()===value.toLowerCase());if(existing)value=existing;else choices.push(value);(country?selectedCountries:selectedSubjects).add(value);options(country?'countryOptions':'subjectOptions',choices.sort(),country?'Country':'Subject',country?selectedCountries:selectedSubjects);el.value='';markDirty();}
$('addCountry').addEventListener('click',()=>addChoice('country'));$('addSubject').addEventListener('click',()=>addChoice('subject'));for(const [id,type] of [['newCountry','country'],['newSubject','subject']])$(id).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();addChoice(type)}});
$('prepareResearch').addEventListener('click',()=>{const f=draftFilters();const text=`Research bachelor’s programmes for intake year 2027.\nStudy countries: ${f.countries.join(', ')||countryChoices.join(', ')}.\nSubjects: ${f.subjects.join(', ')||'Economics and/or Criminology, including related Criminal Justice options'}.\nRequired majors: ${f.majors.join(' + ')||'Any relevant major'}.\nRequired minors: ${f.minors.join(' + ')||'No required minor'}.\nStructure: ${kinds[f.structure]||'Include single majors, multiple majors, minors, joint degrees and double degrees, clearly distinguished'}.\n${f.minorNumber?'Number of minors: '+f.minorNumber+'.\n':''}Applicant: lives in India; verify school-qualification eligibility separately.\nUse current official university sources. Include foreign branch campuses and partner-delivered degrees in each study country, verifying local programme availability. Do not infer availability from a home-campus catalogue. Verify complete combinations rather than combining unrelated subject lists.\nReturn a single table with study country first, university, awarding country/provider, degree and subject roles, application steps, opening dates/deadlines, programme start, evidence links and verification status. Clearly flag unknown 2027 dates and conditional plans.\nThen update my existing 2027 University Admissions Explorer Site (project appgprj_6ae42f5ace008191980f60053a373512) with the verified results, preserving existing entries and access.\nDo not claim that a search of the saved list is fresh internet research.`;$('researchPrompt').value=text;$('researchRequest').hidden=false;$('copyStatus').textContent='Ready to copy into ChatGPT. This has not run a web search.';});
$('copyResearch').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('researchPrompt').value);$('copyStatus').textContent='Copied. Paste into ChatGPT to run the fresh research.'}catch{$('researchPrompt').focus();$('researchPrompt').select();$('copyStatus').textContent='Select and copy the request above, then paste it into ChatGPT.'}});
document.addEventListener('click',e=>{if(!e.target.closest('.multi-picker'))for(const d of document.querySelectorAll('.multi-picker'))d.open=false});
$('rows').addEventListener('click',e=>{const btn=e.target.closest('[data-save]');if(!btn)return;const id=btn.dataset.save,removing=saved.has(id);removing?saved.delete(id):saved.add(id);try{localStorage.setItem('next-chapter-2027-shortlist',JSON.stringify([...saved]));toast(removing?'Removed from your shortlist':'Saved to your shortlist in this browser')}catch{toast('Shortlist updated for this visit; browser storage is unavailable')}render()});
$('export').addEventListener('click',()=>{const rows=filtered();if(!rows.length){toast('No matching routes to export');return}const f=filters(),keys=['country','university','degree','structure','awardingUniversity','awardingCountry','provider','delivery','language','steps','dates','start','status','url'];const heads=['Study country','University','Degree','Options','Awarding university','Awarding country','Teaching provider','Delivery type','Language','Application steps','Application dates','Programme start','Date verification','Official source','Matching study plans','Structure evidence','Checked'];const quote=v=>'"'+String(v).replace(/"/g,'""')+'"';const csv='\ufeff'+[heads,...rows.map(r=>[...keys.map(k=>r[k]),StudyMatch.matchingPlans(r,f).map(p=>`${kinds[StudyMatch.structureOf(p)]}: majors ${p.majors.join(' + ')}; minors ${p.minors.join(' + ')||'none'}; ${p.evidence}${p.note?'; '+p.note:''}`).join(' | '),[...new Set(StudyMatch.matchingPlans(r,f).map(p=>p.source))].join(' | '),r.checked])].map(row=>row.map(quote).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='University_Admissions_2027.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${rows.length} routes exported`)});
function options(container,values,role,selection=new Set()){$(container).innerHTML=values.map(v=>`<label><input type="checkbox" ${selection.has(v)?'checked':''} value="${esc(v)}" aria-label="${role}: ${esc(v)}">${esc(v)}</label>`).join('')}
$('runSearch').disabled=true;
fetch('data.json').then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json()}).then(rows=>{data=rows;countryChoices=[...new Set(data.map(r=>r.country))].sort();subjectChoices=[...new Set(data.flatMap(r=>[...r.subjects.split(','),...r.majors,...r.minors]))].sort();options('countryOptions',countryChoices,'Country',selectedCountries);options('subjectOptions',subjectChoices,'Subject',selectedSubjects);$('runSearch').disabled=false;applied=draftFilters();render()}).catch(()=>{$('rows').innerHTML='<tr><td colspan="9">Unable to load the programme list. Please refresh to try again.</td></tr>';$('count').textContent='0';$('searchState').textContent='The saved list could not load; search is unavailable until it loads successfully.'});
fetch('coverage.json').then(r=>{if(!r.ok)throw Error('Review unavailable');return r.json()}).then(rows=>{$('coverageCards').innerHTML=rows.map(r=>`<article class="coverage-card"><h3>${flags[r.country]} ${esc(r.country)}</h3><div class="scope">${esc(r.scope)}</div><p>${esc(r.finding)}</p>${r.links.map(([name,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(name)} ↗</a>`).join('')}</article>`).join('')}).catch(()=>{$('coverageCards').textContent='Country review details could not load. Please refresh.'});
